cd <E>/trials/t01/ws && node -e "
import { shipOrder, ShipmentStateError } from './src/shipping/domain/shipment.ts';

// Test 1: Pending order should ship successfully
const pendingOrder = { id: 'o1', customerId: 'alice', status: 'pending', items: ['sku-1'] };
const shipped = shipOrder(pendingOrder);
console.log('Test 1 (pending -> shipped):', shipped.status === 'shipped' ? 'PASS' : 'FAIL');

// Test 2: Cancelled order should throw error
const cancelledOrder = { id: 'o2', customerId: 'bob', status: 'cancelled', items: ['sku-2'] };
try {
  shipOrder(cancelledOrder);
  console.log('Test 2 (cancelled -> error): FAIL - no error thrown');
} catch (e) {
  if (e instanceof ShipmentStateError && e.message.includes('cancelled')) {
    console.log('Test 2 (cancelled -> error): PASS');
  } else {
    console.log('Test 2 (cancelled -> error): FAIL - wrong error');
  }
}

// Test 3: Shipped order should stay unchanged
const shippedOrder = { id: 'o3', customerId: 'charlie', status: 'shipped', items: ['sku-3'] };
try {
  shipOrder(shippedOrder);
  console.log('Test 3 (shipped -> error): Expected to fail but did not');
} catch (e) {
  console.log('Test 3 (shipped -> unchanged): Got expected error for shipped order');
}
"

