import assert from 'node:assert/strict';
import {shipOrder, ShipmentStateError} from './src/shipping/domain/shipment.ts';
for (const frozen of [false,true]) {
  for (const status of ['cancelled','pending']) {
    const order={id:'probe',customerId:'alice',status,items:['sku-1']};
    const before=structuredClone(order);
    if(frozen){Object.freeze(order.items);Object.freeze(order);}
    if(status==='cancelled') assert.throws(()=>shipOrder(order),ShipmentStateError);
    else {
      const shipped=shipOrder(order);
      assert.deepEqual(shipped,{...before,status:'shipped'});
      assert.notStrictEqual(shipped,order);
    }
    assert.deepEqual(order,before);
    console.log(`${status}, frozen=${frozen}: PASS; input unchanged`);
  }
}
JS
